{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260925T221232Z/cell-rmGfH9/src/model.js","content":"/**
 * The in-memory document tree the parser builds and the formatters walk.
 *
 * A table is a `TableNode`; a plain array or an array of tables is an
 * `ArrayNode` (the `isArrayOfTables` flag distinguishes the two for header
 * handling, though both report as `array` to the outside world). Scalars are
 * plain `{ type, value }` records.
 */

export class TableNode {
  constructor() {
    this.entries = new Map()
    // Set once a bare `[name]` header has made this table current, so a
    // second such header targeting the same path can be rejected.
    this.headerMadeCurrent = false
  }
}

export class ArrayNode {
  constructor(isArrayOfTables) {
    this.items = []
    this.isArrayOfTables = isArrayOfTables
  }
}

export function scalar(type, value) {
  return { type, value }
}

export function typeOf(node) {
  if (node instanceof TableNode) return 'table'
  if (node instanceof ArrayNode) return 'array'
  return node.type
}
"}

