{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260925T221232Z/cell-rmGfH9/src/lexer.js","content":"/**
 * Character-level parsing for a single directive line: names, quoted
 * strings and value tokens. `Cursor` tracks the read position within one
 * line; nothing here ever crosses a newline, since every directive fits on
 * one line.
 */
import { ParseError } from './errors.js'

const BARE_NAME_CHAR = /[A-Za-z0-9_-]/

export class Cursor {
  constructor(line) {
    this.line = line
    this.pos = 0
  }

  peek() {
    return this.line[this.pos]
  }

  atLineEnd() {
    const ch = this.line[this.pos]
    return ch === undefined || ch === '#' || ch === ';'
  }

  skipWs() {
    while (this.line[this.pos] === ' ' || this.line[this.pos] === '\t') this.pos++
  }
}

/** Parses one basic (`"..."`) or literal (`'...'`) quoted string. */
function parseQuotedString(cursor, lineNo) {
  const quote = cursor.line[cursor.pos]
  const basic = quote === '"'
  cursor.pos++
  let text = ''
  for (;;) {
    const ch = cursor.line[cursor.pos]
    if (ch === undefined) throw new ParseError(lineNo, 'unterminated string')
    if (ch === quote) {
      cursor.pos++
      return text
    }
    if (basic && ch === '\\') {
      cursor.pos++
      const esc = cursor.line[cursor.pos]
      if (esc === undefined) throw new ParseError(lineNo, 'unterminated string')
      switch (esc) {
        case '"':
          text += '"'
          cursor.pos++
          break
        case '\\':
          text += '\\'
          cursor.pos++
          break
        case 'n':
          text += '\n'
          cursor.pos++
          break
        case 't':
          text += '\t'
          cursor.pos++
          break
        case 'r':
          text += '\r'
          cursor.pos++
          break
        case '0':
          text += '\0'
          cursor.pos++
          break
        case 'u': {
          const hex = cursor.line.slice(cursor.pos + 1, cursor.pos + 5)
          if (hex.length !== 4 || !/^[0-9A-Fa-f]{4}$/.test(hex)) {
            throw new ParseError(lineNo, 'invalid escape \\u')
          }
          text += String.fromCharCode(parseInt(hex, 16))
          cursor.pos += 5
          break
        }
        default:
          throw new ParseError(lineNo, `invalid escape \\${esc}`)
      }
      continue
    }
    text += ch
    cursor.pos++
  }
}

/** Parses one name: a bare word or a quoted string. */
export function parseName(cursor, lineNo) {
  const ch = cursor.line[cursor.pos]
  if (ch === '"' || ch === "'") return parseQuotedString(cursor, lineNo)
  if (ch !== undefined && BARE_NAME_CHAR.test(ch)) {
    let start = cursor.pos
    while (cursor.line[cursor.pos] !== undefined && BARE_NAME_CHAR.test(cursor.line[cursor.pos])) cursor.pos++
    return cursor.line.slice(start, cursor.pos)
  }
  throw new ParseError(lineNo, 'expected a name')
}

/** Parses a dotted name: names joined by `.`, with whitespace allowed around each dot. */
export function parseDottedName(cursor, lineNo) {
  cursor.skipWs()
  const names = [parseName(cursor, lineNo)]
  for (;;) {
    cursor.skipWs()
    if (cursor.line[cursor.pos] !== '.') break
    cursor.pos++
    cursor.skipWs()
    names.push(parseName(cursor, lineNo))
  }
  return names
}

const BOOL_RE = /^(true|false)$/
const DIGITS = '[0-9]+(?:_[0-9]+)*'
const INT_RE = new RegExp(`^[+-]?${DIGITS}$`)
const FLOAT_RE = new RegExp(
  `^[+-]?${DIGITS}(?:(?:\\.${DIGITS})(?:[eE][+-]?${DIGITS})?|[eE][+-]?${DIGITS})$`
)

const BARE_STOP = new Set([' ', '\t', ',', ']', '}', undefined])

/**
 * Parses a bare value token (boolean, integer or float) by taking the
 * maximal run up to whitespace, `,`, `]`, `}` or line end. A `#`/`;` is
 * deliberately not a stop character here: with no separating whitespace it
 * is text the value ran into, which the caller's classification then
 * rejects.
 */
export function parseBareToken(cursor, lineNo) {
  const start = cursor.pos
  while (!BARE_STOP.has(cursor.line[cursor.pos])) cursor.pos++
  const token = cursor.line.slice(start, cursor.pos)
  if (BOOL_RE.test(token)) return { type: 'boolean', value: token === 'true' }
  if (INT_RE.test(token)) return { type: 'integer', value: Number(token.replace(/_/g, '')) }
  if (FLOAT_RE.test(token)) return { type: 'float', value: Number(token.replace(/_/g, '')) }
  throw new ParseError(lineNo, `invalid value ${token}`)
}

export { parseQuotedString }
"}

