 * Renders a parsed document tree as canonical JSON or as a `keys` listing.
 */
import { TableNode, ArrayNode, typeOf } from './model.js'

/** Compares strings by Unicode code point, as ascending key order requires. */
function compareByCodePoint(a, b) {
  const ca = Array.from(a)
  const cb = Array.from(b)
  const len = Math.min(ca.length, cb.length)
  for (let i = 0; i < len; i++) {
    const pa = ca[i].codePointAt(0)
    const pb = cb[i].codePointAt(0)
    if (pa !== pb) return pa - pb
  }
  return ca.length - cb.length
}

function sortedKeys(table) {
  return [...table.entries.keys()].sort(compareByCodePoint)
}

function renderJson(node, depth) {
  const pad = '  '.repeat(depth)
  const padIn = '  '.repeat(depth + 1)
  if (node instanceof TableNode) {
    const keys = sortedKeys(node)
    if (keys.length === 0) return '{}'
    const lines = keys.map(
      (k) => `${padIn}${JSON.stringify(k)}: ${renderJson(node.entries.get(k), depth + 1)}`
    )
    return `{\n${lines.join(',\n')}\n${pad}}`
  }
  if (node instanceof ArrayNode) {
    if (node.items.length === 0) return '[]'
    const lines = node.items.map((item) => `${padIn}${renderJson(item, depth + 1)}`)
    return `[\n${lines.join(',\n')}\n${pad}]`
  }
  if (node.type === 'boolean') return node.value ? 'true' : 'false'
  // Strings, integers and floats all print the way JSON prints them.
  return JSON.stringify(node.value)
}

export function formatJson(root) {
  return `${renderJson(root, 0)}\n`
}

function walkKeys(node, path, out) {
  out.push(`${path} ${typeOf(node)}`)
  if (node instanceof TableNode) {
    for (const k of sortedKeys(node)) walkKeys(node.entries.get(k), `${path}.${k}`, out)
  } else if (node instanceof ArrayNode) {
    node.items.forEach((item, i) => walkKeys(item, `${path}[${i}]`, out))
  }
}

export function formatKeys(root) {
  const out = []
  for (const k of sortedKeys(root)) walkKeys(root.entries.get(k), k, out)
  return out.length === 0 ? '' : `${out.join('\n')}\n`
