    const keys = sortedKeys(node)
    if (keys.length === 0) return '{}'
    const lines = keys.map(
      (k) => `${padIn}${JSON.stringify(k)}: ${renderJson(node.entries.get(k), depth + 1)}`
    )
    return `{\n${lines.join(',\n')}\n${pad}}`
  }
  if (node instanceof ArrayNode) {
    if (node.items.length === 0) return '[]'
    const lines = node.items.map((item) => `${padIn}${renderJson(item, depth + 1)}`)
    return `[\n${lines.join(',\n')}\n${pad}]`
  }
  if (node.type === 'boolean') return node.value ? 'true' : 'false'
  // Strings, integers and floats all print the way JSON prints them.
  return JSON.stringify(node.value)
}

